<header class="topbar"><button class="menu-toggle" data-sidebar-open aria-label="Abrir menu">☰</button><div><small><?= e($dashboardName) ?></small><h1><?= e($pageTitle ?? 'Dashboard') ?></h1></div><?php if(($dashboardArea??'')==='seller'&&!empty($currentStore)): $availableStores=(new App\Services\Stores\SellerStoreContext())->stores();?><form class="store-switcher" method="post" action="<?= e(url('/vendedor/selecionar-loja')) ?>"><?= csrf_field() ?><label><span>Loja atual</span><select name="store_id" onchange="this.form.submit()" aria-label="Selecionar loja"><?php foreach($availableStores as $availableStore):?><option value="<?= $availableStore['id'] ?>" <?= (int)$availableStore['id']===(int)$currentStore['id']?'selected':'' ?>><?= e($availableStore['name']) ?></option><?php endforeach;?></select></label></form><?php endif;?><div class="user-chip"><span><?= e(mb_substr($authUser['name'] ?? 'U', 0, 1)) ?></span><div><strong><?= e($authUser['name'] ?? '') ?></strong><small><?= e($authUser['email'] ?? '') ?></small></div></div></header>
